-- POPIA 2026 Stage 1 pack (ISO 27701-aligned auditor sheets) + SME/large branch.
-- Source: docs/assessment-sheets/assessment_popi_2026_1.zip
-- Rows between the PACK/LEGEND markers are generated by app/tests/generate_popia_2026_migration.py
-- from that zip; app/tests/test_popia_2026_pack_parity.py asserts they match.

BEGIN;

ALTER TABLE public.client_orgs
  ADD COLUMN IF NOT EXISTS org_scale text CHECK (org_scale IS NULL OR org_scale IN ('sme', 'large'));
COMMENT ON COLUMN public.client_orgs.org_scale IS
  'Advisor-deemed organisation scale. SME edition in the 2026 POPIA pack is ≤10 users.';

ALTER TABLE public.assessment_sessions
  ADD COLUMN IF NOT EXISTS org_scale text CHECK (org_scale IS NULL OR org_scale IN ('sme', 'large'));
COMMENT ON COLUMN public.assessment_sessions.org_scale IS
  'Snapshot of client org_scale at assessment create. Scoring and question load use this, not the live client value.';

ALTER TABLE public.assessment_questions
  ADD COLUMN IF NOT EXISTS applies_to text NOT NULL DEFAULT 'all'
    CHECK (applies_to IN ('all', 'sme', 'large'));
COMMENT ON COLUMN public.assessment_questions.applies_to IS
  'all = every org; large = large-only (the 17 S4 extras). SME branch is applies_to=all.';

ALTER TABLE public.content_packs
  ADD COLUMN IF NOT EXISTS metadata jsonb;

UPDATE public.assessment_questions
   SET active = FALSE
 WHERE framework = 'popia' AND active = TRUE;

INSERT INTO public.content_packs (practice_id, framework_key, version, label, status, metadata)
VALUES (NULL, 'popia', 2, 'POPIA ISO27701 audit 2026', 'published',
-- POPIA_2026_LEGEND_BEGIN
$p${
  "framework_legend": [
    {
      "framework": "POPIA (Act 4 of 2013)",
      "applicability": "🇿🇦 Mandatory — SA law",
      "description": "Protection of Personal Information Act. All organisations processing personal information in South Africa must comply. s.19 mandates security safeguards. s.21 governs operators. s.22 requires breach notification within 72 hours. s.14 governs retention. Penalty: up to R10M fine and/or imprisonment."
    },
    {
      "framework": "Cyber Essentials (CE / CE+)",
      "applicability": "🇬🇧 UK voluntary; strongly recommended for SMEs",
      "description": "UK government-backed scheme defining five foundational technical controls: (1) Boundary Firewalls, (2) Secure Configuration, (3) Access Control, (4) Malware Protection, (5) Patch Management. CE certification is achievable and cost-effective for SMEs. CE+ adds independent technical verification. Cyber Essentials is recognised in South Africa as an SME security baseline reference."
    },
    {
      "framework": "CIS Controls v8 — IG1",
      "applicability": "✅ Recommended for all SMEs",
      "description": "Center for Internet Security Controls v8, Implementation Group 1 (IG1). IG1 is the \"essential cyber hygiene\" tier specifically designed for small organisations with limited IT resources. Contains 56 safeguards across 18 control families. Free to implement — no certification required. Globally recognised. Directly maps to NIST CSF and ISO 27001. IG1 is the most practical SME-targeted framework available."
    },
    {
      "framework": "NIST CSF 2.0",
      "applicability": "✅ Recommended for all SMEs",
      "description": "NIST Cybersecurity Framework 2.0 (February 2024). Six functions: Govern (GV), Identify (ID), Protect (PR), Detect (DE), Respond (RS), Recover (RC). Flexible, risk-based, and scalable to any organisation size. Free to use. Strong alignment with POPIA security obligations. Provides common language for discussing cybersecurity risk with management and boards."
    },
    {
      "framework": "ISO 27001:2022",
      "applicability": "⭐ Aspirational for SMEs; certifiable",
      "description": "International standard for Information Security Management Systems (ISMS). ISO 27001 certification demonstrates security maturity to clients, regulators, and partners. Annex A provides 93 controls. ISO 27001 is the most recognised security standard globally. SMEs can implement the standard without pursuing certification initially. Strongly aligns with POPIA s.19 security obligations."
    },
    {
      "framework": "ISO 27002:2022",
      "applicability": "✅ Implementation guidance for ISO 27001",
      "description": "Provides detailed implementation guidance for ISO 27001 Annex A controls. Not a certification standard — used alongside ISO 27001. Referenced in this audit for specific technical and organisational control guidance."
    },
    {
      "framework": "ISO 27701:2019",
      "applicability": "⭐ Privacy extension to ISO 27001",
      "description": "Privacy Information Management System (PIMS) standard. Extends ISO 27001 to address privacy-specific obligations including POPIA and GDPR. Directly maps to POPIA conditions. Provides specific controls for personal information controllers and processors. Certifiable as an extension to ISO 27001."
    },
    {
      "framework": "NIST SP 800-171",
      "applicability": "🔵 Relevant for orgs handling sensitive/govt data",
      "description": "NIST Special Publication 800-171. Protecting Controlled Unclassified Information (CUI) in non-federal systems. Relevant for SMEs supplying government or defence clients. 110 security requirements across 14 families. Referenced in this audit where controls directly overlap with POPIA security obligations."
    },
    {
      "framework": "ISO 22301:2019",
      "applicability": "⭐ Applicable for BCP/DRP",
      "description": "Business Continuity Management System standard. Provides methodology for planning, establishing, implementing, and testing BCP and DRP. Referenced for backup and continuity questions. SMEs can implement ISO 22301 principles without pursuing certification."
    }
  ]
}$p$
-- POPIA_2026_LEGEND_END
);

INSERT INTO public.assessment_questions
  (framework, content_pack_id, section_id, section_name, subsection, question_number,
   question, why_matters, regulatory_ref, risk, evidence_req, remediation, applies_to, uid)
SELECT 'popia', cp.id, x.section_id, x.section_name, x.subsection, x.qn,
       x.question, x.why, x.ref, x.risk, x.evidence, x.remediation, x.applies_to, x.uid
FROM (SELECT id FROM public.content_packs
      WHERE framework_key = 'popia' AND version = 2 AND practice_id IS NULL) cp,
(VALUES
-- POPIA_2026_PACK_ROWS_BEGIN
  (1, $p$Procedural Issues & Awareness$p$, $p$GOVERNANCE & ACCOUNTABILITY$p$, 1, $p$Has the organisation formally adopted a Privacy Information Management System (PIMS) or privacy governance framework aligned to POPIA and ISO 27701?$p$, $p$$p$, $p$POPIA s.21, s.55 | ISO 27701 cl.5.2.1 (Understanding the organisation), cl.5.4 (Leadership)$p$, $p$Critical$p$, $p$Board-approved PIMS policy; ISO 27701 scope document or gap assessment; privacy governance charter; management review minutes$p$, $p$Establish a PIMS by defining the scope, context, and stakeholders per ISO 27701 cl.5.2. Obtain board-level endorsement. Map the PIMS to all POPIA conditions. Conduct an annual management review as required by cl.9.3.$p$, $p$all$p$, $p$popia.s1.q01$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$GOVERNANCE & ACCOUNTABILITY$p$, 2, $p$Has an Information Officer (IO) been formally appointed by name, registered with the Information Regulator, and assigned documented responsibilities aligned to POPIA and PIMS requirements?$p$, $p$$p$, $p$POPIA s.55–56; IR Regulations r.2–4 | ISO 27701 cl.5.3.2 (Organisational roles, responsibilities and authorities)$p$, $p$Critical$p$, $p$IO appointment letter; IR registration confirmation; IO job description referencing POPIA & PIMS duties; organisational chart$p$, $p$Appoint and register the IO with the IR via the online portal. Define the IO's role to include PIMS oversight, data subject request management, breach notification, and regulatory liaison. Publish contact details on the website and in the PAIA Manual.$p$, $p$all$p$, $p$popia.s1.q02$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$GOVERNANCE & ACCOUNTABILITY$p$, 3, $p$Has the organisation conducted a formal context-of-organisation assessment, identifying all internal and external stakeholders with privacy interests (including regulators, processors, and data subjects)?$p$, $p$$p$, $p$POPIA s.21 | ISO 27701 cl.5.2.1, cl.5.2.2 (Needs and expectations of interested parties)$p$, $p$High$p$, $p$Stakeholder register; context assessment document; risk register referencing privacy risks per stakeholder group$p$, $p$Conduct and document a stakeholder/context analysis per ISO 27701 cl.5.2. Identify all parties with legitimate privacy interests. Update at least annually or following material changes to processing activities.$p$, $p$all$p$, $p$popia.s1.q03$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$GOVERNANCE & ACCOUNTABILITY$p$, 4, $p$Is POPIA/PIMS compliance a standing agenda item at board and senior management meetings, with documented decisions and actions?$p$, $p$$p$, $p$POPIA s.55 | ISO 27701 cl.5.1 (Leadership and commitment), cl.9.3 (Management review)$p$, $p$High$p$, $p$Board/management meeting agendas and minutes showing standing POPIA/PIMS item; management review outputs$p$, $p$Add POPIA/PIMS compliance as a mandatory standing item on board and EXCO agendas. Record decisions and corrective actions in minutes. Conduct a formal annual PIMS management review per ISO 27701 cl.9.3.$p$, $p$all$p$, $p$popia.s1.q04$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$POLICIES & PROCEDURES$p$, 5, $p$Does the organisation maintain a current, board-approved Privacy / POPIA Compliance Policy that addresses all eight POPIA conditions and maps to the relevant ISO 27701 controls?$p$, $p$$p$, $p$POPIA s.55; all eight Conditions | ISO 27701 cl.5.2, cl.6.2 (PII-related objectives)$p$, $p$Critical$p$, $p$Signed, version-controlled Privacy Policy with board approval record; POPIA condition-to-policy mapping table; annual review log$p$, $p$Develop or update the Privacy Policy to explicitly address all eight POPIA conditions and cross-reference ISO 27701 controls. Implement version control, obtain board approval, and schedule an annual review cycle.$p$, $p$all$p$, $p$popia.s1.q05$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$POLICIES & PROCEDURES$p$, 6, $p$Does the organisation maintain and publish a PAIA Manual that accurately reflects current processing activities, including a record of processing activities (RoPA)?$p$, $p$$p$, $p$POPIA s.17; PAIA s.51 | ISO 27701 cl.7.2.1 (PII inventory and mapping — controller), cl.8.2.1 (processor)$p$, $p$Critical$p$, $p$Current PAIA Manual (submitted to IR and published on website); RoPA / data inventory listing data categories, purposes, lawful basis, retention periods, and recipients$p$, $p$Update the PAIA Manual to include a comprehensive RoPA per ISO 27701 cl.7.2.1. Submit to the IR and publish on the organisation's website. Review and update the RoPA at least annually and whenever a new processing activity commences.$p$, $p$all$p$, $p$popia.s1.q06$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$POLICIES & PROCEDURES$p$, 7, $p$Are all privacy-related policies and procedures subject to a documented review cycle (minimum annual) with version control and management sign-off?$p$, $p$$p$, $p$POPIA s.55 | ISO 27701 cl.7.5 (Documented information), cl.10.2 (Continual improvement)$p$, $p$High$p$, $p$Policy register with version history, review dates, and approvers; document management system or SharePoint with version control$p$, $p$Establish a formal policy review calendar. Require management sign-off on each revised version. Retain previous versions for audit purposes. Trigger an ad-hoc review following any regulatory change, data breach, or material change in processing.$p$, $p$all$p$, $p$popia.s1.q07$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$POLICIES & PROCEDURES$p$, 8, $p$Does the organisation issue clear and lawful fair processing / privacy notices to data subjects at or before the point of collection, covering all elements required by POPIA s.18?$p$, $p$$p$, $p$POPIA s.18 (Notification) | ISO 27701 cl.7.3 (Determining PII principals' information needs), cl.7.3.2 (Providing privacy notices)$p$, $p$Critical$p$, $p$Privacy notices on all collection touchpoints (web forms, paper forms, call scripts, app onboarding); privacy notice review log; DSAR to test completeness$p$, $p$Audit all data collection touchpoints. Ensure each privacy notice states: identity of the IO, purpose, lawful basis, data subject rights, third-party recipients, cross-border transfer details, and retention period. Review notices annually and update following any change in processing.$p$, $p$all$p$, $p$popia.s1.q08$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$PRIVACY RISK & IMPACT ASSESSMENTS$p$, 9, $p$Does the organisation conduct Privacy Impact Assessments (PIAs) / Data Protection Impact Assessments (DPIAs) for all new or significantly changed processing activities involving personal information?$p$, $p$$p$, $p$POPIA s.69; IR PIA guidance | ISO 27701 cl.6.1.2 (PII-related risk assessment), cl.7.2.5 (Privacy by design and default)$p$, $p$High$p$, $p$PIA/DPIA policy; completed PIA templates for current high-risk processing; PIA register; project management gate approvals linked to PIA sign-off$p$, $p$Embed PIA/DPIA as a mandatory project governance gate. Develop a risk-tiered screening tool to determine when a full PIA is required. Maintain a PIA register. Obtain IO sign-off before new high-risk processing commences.$p$, $p$all$p$, $p$popia.s1.q09$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$PRIVACY RISK & IMPACT ASSESSMENTS$p$, 10, $p$Is Privacy by Design and by Default implemented, ensuring that only the minimum personal information necessary is processed and that privacy-protective defaults are built into systems and products?$p$, $p$$p$, $p$POPIA s.12, s.13 | ISO 27701 cl.7.2.5 (Privacy by design and default)$p$, $p$High$p$, $p$System design specifications showing privacy controls at design stage; data minimisation evidence (form field justification); default settings review; PIA records at design phase$p$, $p$Implement a Privacy by Design checklist as part of IT and product development governance. Require IO review of all new system designs. Default settings must protect privacy (opt-in, not opt-out). Conduct a post-implementation privacy review for all new systems.$p$, $p$all$p$, $p$popia.s1.q10$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$STAFF TRAINING & AWARENESS$p$, 11, $p$Is there a documented, role-based POPIA and privacy awareness training programme, with completion tracked and refresher training provided at least annually?$p$, $p$$p$, $p$POPIA s.55 | ISO 27701 cl.7.4 (Awareness), cl.6.3 (Awareness and training programme for PII handling)$p$, $p$Critical$p$, $p$Training curriculum; LMS or manual training register with completion dates; training materials; annual refresher schedule; non-completion escalation records$p$, $p$Develop role-differentiated training modules (general staff, IT, legal, marketing, HR). Mandate completion within 30 days of onboarding and annually thereafter. Track via LMS. Escalate non-completions to line managers and the IO.$p$, $p$all$p$, $p$popia.s1.q11$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$STAFF TRAINING & AWARENESS$p$, 12, $p$Are staff who handle personal information required to sign a confidentiality/acceptable use agreement that includes post-employment privacy obligations?$p$, $p$$p$, $p$POPIA s.107 | ISO 27701 cl.6.6 (Confidentiality or non-disclosure agreements)$p$, $p$High$p$, $p$Signed confidentiality / NDA agreements referencing personal information; employment contracts with post-termination privacy clause; offboarding checklist confirming return of data assets$p$, $p$Include a post-termination confidentiality clause specifically referencing personal information in all employment contracts. Require staff to sign an Acceptable Use Policy and a confidentiality agreement at onboarding. Confirm during offboarding that all personal information assets have been returned or destroyed.$p$, $p$all$p$, $p$popia.s1.q12$p$),
  (1, $p$Procedural Issues & Awareness$p$, $p$STAFF TRAINING & AWARENESS$p$, 13, $p$Are staff aware of how to recognise and report a personal information breach or suspected security incident to the IO?$p$, $p$$p$, $p$POPIA s.22 | ISO 27701 cl.6.13.1 (Responsibilities and procedures for PII breach management)$p$, $p$Critical$p$, $p$Breach reporting procedure; staff training records on breach identification; breach hotline/mailbox details in staff handbook; drills or tabletop exercises$p$, $p$Publish a clear breach reporting procedure in the staff handbook and intranet. Include breach recognition and reporting in all POPIA training. Operate a dedicated breach reporting email or hotline. Conduct annual tabletop exercises to test staff response.$p$, $p$all$p$, $p$popia.s1.q13$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$PROCESSING LIMITATION & LAWFUL BASIS$p$, 1, $p$Has the organisation identified, documented, and mapped a specific lawful basis under POPIA s.11 for each processing activity in the RoPA?$p$, $p$$p$, $p$POPIA s.11 (Grounds for lawful processing); s.9 | ISO 27701 cl.7.2.2 (Determining lawful basis), cl.7.2.3$p$, $p$Critical$p$, $p$RoPA / processing register with lawful basis column; legal opinion for reliance on legitimate interest or public interest; consent records; contractual necessity documentation$p$, $p$Review the RoPA and confirm a documented lawful basis under s.11 for every processing activity. Where legitimate interest is relied upon, conduct and document a legitimate interest assessment (LIA). Ensure the lawful basis is reflected in the applicable privacy notice.$p$, $p$all$p$, $p$popia.s2.q01$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$PROCESSING LIMITATION & LAWFUL BASIS$p$, 2, $p$Where consent is the lawful basis, is it obtained in a manner that is freely given, specific, informed, unambiguous, and separately recorded per data subject and purpose?$p$, $p$$p$, $p$POPIA s.11(1)(a); s.69 | ISO 27701 cl.7.2.3 (Determining when and how consent is to be obtained), cl.7.3.4$p$, $p$Critical$p$, $p$Consent management system or CRM with consent records (timestamp, version of wording, channel, purpose); opt-in consent forms (no pre-ticked boxes); consent withdrawal records$p$, $p$Implement a consent management platform or configure the CRM to capture consent per data subject, per purpose, per channel, with a timestamp and version of the consent wording accepted. Audit consent records quarterly.$p$, $p$all$p$, $p$popia.s2.q02$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$PROCESSING LIMITATION & LAWFUL BASIS$p$, 3, $p$Is there a documented process for withdrawing consent, and is withdrawal actioned promptly (within 5 business days) with processing ceasing immediately where consent was the sole basis?$p$, $p$$p$, $p$POPIA s.11(3) | ISO 27701 cl.7.3.5 (Providing mechanism to modify or withdraw consent)$p$, $p$High$p$, $p$Consent withdrawal procedure; withdrawal request log with action dates; suppression list updates; evidence of processing cessation$p$, $p$Implement a simple, accessible consent withdrawal mechanism (online form, email, telephone). Define an SLA of 5 business days for actioning withdrawal. Confirm cessation of processing to the data subject in writing.$p$, $p$all$p$, $p$popia.s2.q03$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$PROCESSING LIMITATION & LAWFUL BASIS$p$, 4, $p$Has the organisation identified all special personal information (health, biometrics, race, religion, sex life, criminal records, children's data) and documented a specific additional condition under POPIA s.27 for each?$p$, $p$$p$, $p$POPIA s.26–33 (Special Personal Information); s.34–38 (Children's PI) | ISO 27701 cl.7.2.8 (Processing of sensitive PII)$p$, $p$Critical$p$, $p$Special PI register; legal basis documentation per s.27 for each category; additional consent forms (explicit written consent); heightened security controls evidence$p$, $p$Identify all special PI categories processed. For each, document the applicable s.27 condition. Implement heightened controls: explicit consent, restricted access, encryption at rest and in transit, separate storage, and enhanced retention controls.$p$, $p$all$p$, $p$popia.s2.q04$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$PURPOSE SPECIFICATION$p$, 5, $p$Are personal information processing purposes defined with sufficient specificity, documented in the RoPA, and consistently communicated to data subjects in privacy notices?$p$, $p$$p$, $p$POPIA s.13 (Purpose specification); s.18 | ISO 27701 cl.7.2.1 (RoPA), cl.7.3.2 (Privacy notices)$p$, $p$Critical$p$, $p$RoPA with granular purpose descriptions; corresponding privacy notices referencing each purpose; internal purpose definition policy$p$, $p$Review all processing activities and ensure purposes are stated at a granular level (not generic). Cross-check that the RoPA and the applicable privacy notices use consistent, specific purpose language. Avoid bundled or open-ended purpose statements.$p$, $p$all$p$, $p$popia.s2.q05$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$PURPOSE SPECIFICATION$p$, 6, $p$Is personal information used strictly for the purpose for which it was collected, and is any further processing assessed for compatibility before it occurs?$p$, $p$$p$, $p$POPIA s.15 (Further processing limitation) | ISO 27701 cl.7.2.6 (PII processing for specified purpose only)$p$, $p$High$p$, $p$Further processing compatibility assessment records; IO approval records for secondary use; updated privacy notices where further processing approved; audit logs confirming purpose adherence$p$, $p$Implement a further processing compatibility test (assessing link to original purpose, context, nature of data, consequences, and safeguards). Require IO approval before any secondary use. Where incompatible, obtain fresh consent and update the privacy notice.$p$, $p$all$p$, $p$popia.s2.q06$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$PURPOSE SPECIFICATION$p$, 7, $p$Does the organisation have a documented procedure for responding to third-party requests for personal information, including requests from law enforcement, and is a log of all such disclosures maintained?$p$, $p$$p$, $p$POPIA s.11(1)(b)–(f); PAIA | ISO 27701 cl.7.2.7 (Disclosures to third parties)$p$, $p$High$p$, $p$Third-party disclosure procedure; disclosure log (date, requester, legal basis cited, data disclosed, IO approval); legal hold register$p$, $p$Develop a Third-Party Disclosure Procedure requiring IO or legal review before any disclosure. Maintain a disclosure log. Require law enforcement requests to cite a specific statutory authority before disclosure is made.$p$, $p$all$p$, $p$popia.s2.q07$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$DATA MINIMISATION & QUALITY$p$, 8, $p$Are data collection forms, systems, and processes reviewed regularly to ensure that only the minimum personal information necessary for the stated purpose is collected (data minimisation)?$p$, $p$$p$, $p$POPIA s.12 (Collection directly from data subject) | ISO 27701 cl.7.2.5 (Privacy by design — data minimisation)$p$, $p$High$p$, $p$Form/field justification log; data minimisation review records; PIA outputs; records of fields removed following review$p$, $p$Conduct an annual data minimisation audit of all data collection touchpoints. Require field-level justification for each personal information item collected. Remove or anonymise fields that cannot be justified against a specific processing purpose.$p$, $p$all$p$, $p$popia.s2.q08$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$DATA MINIMISATION & QUALITY$p$, 9, $p$Does the organisation have documented procedures to ensure the accuracy, completeness, and currency of personal information, including a process for data subjects to request correction?$p$, $p$$p$, $p$POPIA s.16 (Quality of information) | ISO 27701 cl.7.4.3 (Inaccurate or incomplete PII)$p$, $p$Medium$p$, $p$Data accuracy procedure; annual data refresh communications; CRM/system data quality reports; correction request log and resolution records$p$, $p$Implement periodic data quality reviews (minimum annually). Send data verification communications to data subjects at least once per year. Maintain a correction request log and resolve corrections within the 30-day statutory period.$p$, $p$all$p$, $p$popia.s2.q09$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$TRANSBORDER INFORMATION FLOWS$p$, 10, $p$Has the organisation identified and documented all cross-border transfers of personal information, including transfers to cloud service providers and group companies in other countries?$p$, $p$$p$, $p$POPIA s.72 (Transborder information flows) | ISO 27701 cl.7.5.1 (Basis for PII transfer between jurisdictions)$p$, $p$High$p$, $p$Cross-border transfer register (recipient country, data categories, transfer mechanism, adequacy status); cloud service provider list with data location; intra-group data transfer agreements$p$, $p$Conduct a cross-border transfer mapping exercise. Include cloud hosting locations, SaaS platforms, intra-group transfers, and outsourced processing. Document each transfer in the RoPA and the cross-border transfer register.$p$, $p$all$p$, $p$popia.s2.q10$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$TRANSBORDER INFORMATION FLOWS$p$, 11, $p$For each cross-border transfer, has a lawful transfer mechanism been confirmed and documented (adequacy, binding corporate rules, standard contractual clauses, explicit consent, or public interest)?$p$, $p$$p$, $p$POPIA s.72(1)(a)–(f) | ISO 27701 cl.7.5.1, cl.7.5.2 (Countries and international organisations to which PII may be transferred)$p$, $p$Critical$p$, $p$Adequacy assessment per recipient country; signed data transfer agreements (standard contractual clauses or binding corporate rules); explicit consent records where used as the transfer mechanism$p$, $p$For each cross-border transfer destination, determine whether the country has adequate data protection legislation. Where adequacy cannot be confirmed, implement a POPIA-compliant data transfer agreement (incorporating standard contractual clauses) before any transfer takes place.$p$, $p$all$p$, $p$popia.s2.q11$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$OPERATOR / PROCESSOR MANAGEMENT$p$, 12, $p$Does the organisation maintain a register of all operators (third-party processors) that process personal information on its behalf, and is a POPIA-compliant written Data Processing Agreement (DPA) in place with each?$p$, $p$$p$, $p$POPIA s.20–22 (Operators) | ISO 27701 cl.7.2.7, cl.6.12 (Supplier relationships), cl.8.5 (Operator obligations — processor perspective)$p$, $p$Critical$p$, $p$Operator register; signed DPAs with each operator; operator onboarding checklist; annual operator review records$p$, $p$Identify all operators via a supplier mapping exercise. Ensure a POPIA-compliant DPA is executed before any personal information is shared. The DPA must include: processing instructions, security obligations, breach notification obligations, sub-processor restrictions, and audit rights.$p$, $p$all$p$, $p$popia.s2.q12$p$),
  (2, $p$Lawful Processing of Personal Information$p$, $p$OPERATOR / PROCESSOR MANAGEMENT$p$, 13, $p$Are operators assessed for POPIA / ISO 27701 compliance before engagement and monitored on an ongoing basis?$p$, $p$$p$, $p$POPIA s.21 (Accountability); s.19(2) | ISO 27701 cl.6.12.1 (Supplier relationships — information security in supplier relationships)$p$, $p$High$p$, $p$Operator pre-engagement assessment questionnaire; ISO 27001/27701 certifications or equivalent; annual compliance review records; right-to-audit clause in DPA$p$, $p$Implement a third-party risk assessment process for all operators before engagement. Require ISO 27001 certification or equivalent assurance. Conduct annual compliance reviews. Include a right-to-audit clause in all DPAs and exercise this right for high-risk operators at least every two years.$p$, $p$all$p$, $p$popia.s2.q13$p$),
  (3, $p$Record Retention$p$, $p$DATA MAPPING & ASSET INVENTORY$p$, 1, $p$Has the organisation conducted a comprehensive data mapping exercise covering all personal information held in structured systems (databases, CRM, HR, ERP), unstructured environments (email, file shares, cloud storage), and physical files?$p$, $p$$p$, $p$POPIA s.17; s.14 | ISO 27701 cl.7.2.1 (RoPA — controller), cl.8.2.1 (RoPA — processor)$p$, $p$Critical$p$, $p$Data mapping report; RoPA / data inventory listing systems, data categories, locations, owners, retention periods; data flow diagrams$p$, $p$Conduct a data mapping exercise using automated discovery tools where available. Document all personal information assets in a RoPA. Assign a data owner to each asset. Review and update the RoPA at least annually and whenever a new system or processing activity is introduced.$p$, $p$all$p$, $p$popia.s3.q01$p$),
  (3, $p$Record Retention$p$, $p$DATA MAPPING & ASSET INVENTORY$p$, 2, $p$Does the organisation maintain an up-to-date information asset register that classifies personal information by sensitivity (e.g. general, special/sensitive, children's data) and maps it to the applicable retention period?$p$, $p$$p$, $p$POPIA s.26–34; s.14 | ISO 27701 cl.7.2.1; ISO 27002 cl.5.9 (Inventory of information and other associated assets)$p$, $p$High$p$, $p$Information asset register with classification column; data classification policy; retention schedule cross-referenced to the asset register; annual review records$p$, $p$Implement a data classification policy with defined tiers (Public / Internal / Confidential / Restricted). Apply classification to all assets in the information asset register. Cross-reference classification to the retention schedule and applicable security controls.$p$, $p$all$p$, $p$popia.s3.q02$p$),
  (3, $p$Record Retention$p$, $p$RETENTION POLICY & SCHEDULE$p$, 3, $p$Does the organisation have a board-approved Record Retention Policy with a detailed retention schedule specifying retention periods for all categories of personal information, referenced to applicable legislation?$p$, $p$$p$, $p$POPIA s.14 (Retention and restriction of records) | ISO 27701 cl.7.4.7 (Minimum necessary PII — retention), cl.7.5 (Documented information)$p$, $p$Critical$p$, $p$Signed, approved Record Retention Policy; retention schedule (data category, retention period, legal basis for period, disposal method, owner); board approval record; annual review log$p$, $p$Develop a Record Retention Policy and schedule. Map each personal information category to its statutory or business retention period. Cross-reference applicable legislation (POPIA, Companies Act 71 of 2008, Tax Administration Act 28 of 2011, FICA, FAIS, National Credit Act). Obtain board approval and review annually.$p$, $p$all$p$, $p$popia.s3.q03$p$),
  (3, $p$Record Retention$p$, $p$RETENTION POLICY & SCHEDULE$p$, 4, $p$Are retention periods aligned with all applicable South African sector-specific legislation and are conflicts between different statutory retention periods formally resolved and documented?$p$, $p$$p$, $p$POPIA s.14; s.15 | ISO 27701 cl.7.4.7; relevant sector legislation$p$, $p$High$p$, $p$Statutory retention mapping table (POPIA vs. Companies Act vs. Tax Administration Act vs. FICA vs. FAIS etc.); legal opinion for conflicting periods; retention schedule showing the longer of applicable periods applied$p$, $p$Commission a statutory retention mapping exercise. Where multiple obligations apply to the same data category, apply the longer of the required retention periods. Document the rationale. Obtain legal sign-off on the completed retention schedule.$p$, $p$all$p$, $p$popia.s3.q04$p$),
  (3, $p$Record Retention$p$, $p$DELETION, DESTRUCTION & DE-IDENTIFICATION$p$, 5, $p$Is personal information deleted, destroyed, or de-identified as soon as the purpose for which it was collected or processed has lapsed and no legal retention obligation applies?$p$, $p$$p$, $p$POPIA s.14(1) | ISO 27701 cl.7.4.7 (Retention of PII), cl.7.4.8 (Disposal of PII)$p$, $p$Critical$p$, $p$Automated deletion/archiving rules in CRM, HR, ERP systems; manual deletion procedure for systems without automation; deletion logs with dates and data categories; de-identification procedure and sample output$p$, $p$Implement automated retention enforcement rules in all major systems. For systems without automation, define a manual deletion procedure with quarterly execution. Maintain deletion/destruction certificates for every disposal event.$p$, $p$all$p$, $p$popia.s3.q05$p$),
  (3, $p$Record Retention$p$, $p$DELETION, DESTRUCTION & DE-IDENTIFICATION$p$, 6, $p$Does the organisation have a documented procedure for the secure destruction of personal information in both paper and electronic format, including media sanitisation standards?$p$, $p$$p$, $p$POPIA s.14; s.19 | ISO 27701 cl.7.4.8; ISO 27002 cl.7.14 (Secure disposal or reuse of equipment)$p$, $p$High$p$, $p$Destruction policy; cross-cut shredder (DIN 66399 Level P-4 or higher) usage records; electronic media sanitisation standard (NIST 800-88 or equivalent); certificates of destruction; vendor contracts for secure shredding$p$, $p$Implement a media sanitisation standard (NIST SP 800-88 or equivalent) for all electronic media. Require cross-cut shredding (minimum DIN 66399 P-4) for paper records. Engage vetted destruction vendors with POPIA-compliant contracts. Retain destruction certificates.$p$, $p$all$p$, $p$popia.s3.q06$p$),
  (3, $p$Record Retention$p$, $p$DELETION, DESTRUCTION & DE-IDENTIFICATION$p$, 7, $p$Where personal information is de-identified as an alternative to deletion, is the de-identification process documented, tested, and confirmed to prevent re-identification?$p$, $p$$p$, $p$POPIA s.1 (definition of de-identified); s.14 | ISO 27701 cl.7.4.8; NIST 800-188$p$, $p$High$p$, $p$De-identification methodology documentation; re-identification risk assessment; testing results confirming k-anonymity or equivalent; classification of de-identified data vs. personal information$p$, $p$Define a de-identification standard appropriate to the sensitivity of the data (e.g. k-anonymity, l-diversity, differential privacy). Conduct and document a re-identification risk assessment before treating data as de-identified. Reassess if new auxiliary data sources become available.$p$, $p$all$p$, $p$popia.s3.q07$p$),
  (3, $p$Record Retention$p$, $p$ARCHIVE & DATABASE MAINTENANCE$p$, 8, $p$Are off-site or cloud archival storage locations included in the data inventory, subject to POPIA-compliant operator agreements, and reviewed periodically for records past their retention period?$p$, $p$$p$, $p$POPIA s.14; s.20–22 | ISO 27701 cl.7.4.7; cl.6.12.1$p$, $p$Medium$p$, $p$Off-site / cloud storage agreements with POPIA DPA clauses; access logs for archival storage; periodic archive review records; destruction certificates for records purged from archive$p$, $p$Include all archival and off-site storage in the RoPA. Ensure storage providers have signed DPAs. Conduct a minimum bi-annual archive review to identify and destroy records that have exceeded their retention period.$p$, $p$all$p$, $p$popia.s3.q08$p$),
  (3, $p$Record Retention$p$, $p$ARCHIVE & DATABASE MAINTENANCE$p$, 9, $p$Are operational databases and systems regularly purged of personal information that is no longer required, with purge activities logged and evidence retained?$p$, $p$$p$, $p$POPIA s.14 | ISO 27701 cl.7.4.7, cl.7.4.8$p$, $p$High$p$, $p$Database purge schedule (minimum quarterly); purge logs with execution date, system, data category, record count deleted; automated purge rule configuration screenshots$p$, $p$Establish a quarterly database purge cycle for all operational systems containing personal information. Automate where possible. Log every purge with the date, system, data category, and number of records deleted. Report purge metrics to the IO quarterly.$p$, $p$all$p$, $p$popia.s3.q09$p$),
  (3, $p$Record Retention$p$, $p$ARCHIVE & DATABASE MAINTENANCE$p$, 10, $p$Is there a documented procedure for handling personal information held in backups, ensuring that backup data is also subject to the retention policy and is not retained beyond the applicable retention period?$p$, $p$$p$, $p$POPIA s.14; s.19 | ISO 27701 cl.7.4.7; ISO 27002 cl.8.13 (Information backup)$p$, $p$Medium$p$, $p$Backup retention policy; backup rotation/overwrite schedule; evidence that expired personal information is purged from backups; backup management system configuration$p$, $p$Define the retention period for backup data in the Backup Policy, aligned to the Record Retention Schedule. Implement a backup rotation schedule (e.g. grandfather-father-son). Ensure that once operational retention periods expire, the corresponding data is also purged from backups.$p$, $p$all$p$, $p$popia.s3.q10$p$),
  (4, $p$Security of Personal Information$p$, $p$INFORMATION SECURITY POLICY & GOVERNANCE$p$, 1, $p$Does the organisation have a board-approved Information Security Policy aligned to ISO 27001/27002 and incorporating POPIA s.19 security obligations, reviewed at least annually?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.5.1 (Policies for information security)
[ISO 27002]  cl.5.1 (Policies for information security)
[ISO 27701]  cl.6.2 (Information security objectives)
[CIS Controls v8 IG1]  CIS 14 — Security Awareness & Skills Training (policy documentation); CIS 12.1 — Network Infrastructure Mgmt
[NIST CSF 2.0]  GV.PO-01 (Organisational cybersecurity policy); GV.OC-01 (Organisational context)
[Cyber Essentials]  N/A — policy is foundational but not a direct CE technical control
[NIST SP 800-171]  3.12.1 (Periodically assess security controls)$p$, $p$Critical$p$, $p$Information Security Policy (board-approved, version-controlled); ISO 27001/27701 certification or gap assessment; annual policy review log; staff acknowledgement records$p$, $p$Develop or update the Information Security Policy to explicitly address POPIA s.19 obligations. Align to ISO 27001/27002. Obtain board approval. Review annually and after any significant security incident or regulatory change.$p$, $p$all$p$, $p$popia.s4.q01$p$),
  (4, $p$Security of Personal Information$p$, $p$INFORMATION SECURITY POLICY & GOVERNANCE$p$, 2, $p$Has the organisation conducted a formal information security risk assessment that includes privacy risks to personal information, with a risk treatment plan and residual risk acceptance documented?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.6.1.2 (Risk assessment); A.6.1.3 (Risk treatment)
[ISO 27701]  cl.6.1.2 (PII-specific risk assessment); cl.6.1.3 (Risk treatment)
[CIS Controls v8 IG1]  CIS 18.1 — Establish and Maintain a Penetration Testing Programme (risk baseline)
[NIST CSF 2.0]  ID.RA-01 (Vulnerabilities identified); ID.RA-05 (Threats & vulnerabilities assessed); GV.RM-02 (Risk tolerance established)
[Cyber Essentials]  Risk assessment underpins CE boundary firewall and access control controls
[NIST SP 800-171]  3.11.1 (Risk assessments); 3.11.2 (Vulnerability scans)$p$, $p$Critical$p$, $p$Risk assessment report (including PII-specific risks); risk register; risk treatment plan; residual risk acceptance sign-off by senior management$p$, $p$Conduct an annual information security risk assessment that explicitly includes PII-related risks (unauthorised access, disclosure, loss, alteration). Develop a risk treatment plan. Document residual risk acceptance by management. Update following any material change in the threat landscape.$p$, $p$all$p$, $p$popia.s4.q02$p$),
  (4, $p$Security of Personal Information$p$, $p$PHYSICAL SECURITY$p$, 3, $p$Are physical access controls in place to restrict access to all areas where personal information is stored or processed (server rooms, filing areas, print rooms)?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.7.1 (Physical security perimeters); A.7.2 (Physical entry)
[ISO 27002]  cl.7.2 (Physical entry); cl.7.3 (Securing offices, rooms and facilities)
[ISO 27701]  cl.6.9 (Physical and environmental security)
[CIS Controls v8 IG1]  CIS 10.3 — Disable Autorun (physical media); CIS 13.6 — Collect detailed audit logs
[NIST CSF 2.0]  PR.AA-05 (Physical access to assets managed); PR.PS-01 (Baseline configuration established)
[Cyber Essentials]  Not a direct CE technical control (CE focuses on internet-facing controls); physical security recommended in CE guidance
[NIST SP 800-171]  3.10.1 (Limit physical access); 3.10.2 (Escort visitors and monitor activity)$p$, $p$High$p$, $p$Access control system logs; biometric/key card access records; visitor register; CCTV policy and footage retention records; physical security audit report$p$, $p$Implement electronic access control (biometric or smart card) for all sensitive areas. Maintain a visitor register. Restrict tailgating through anti-passback controls. Review access logs monthly and revoke access for departed staff within 24 hours.$p$, $p$all$p$, $p$popia.s4.q03$p$),
  (4, $p$Security of Personal Information$p$, $p$PHYSICAL SECURITY$p$, 4, $p$Is a clean-desk and clear-screen policy enforced to prevent unauthorised access to personal information on desks or unattended screens?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.7.7 (Clear desk and clear screen)
[ISO 27002]  cl.7.7 (Clear desk and clear screen)
[CIS Controls v8 IG1]  CIS 4.3 — Configure automatic session locking (screen lock ≤5 min)
[NIST CSF 2.0]  PR.AA-02 (Identities verified before access granted); PR.PS-04 (Logs of events generated)
[Cyber Essentials]  Supports CE 'Access Control' control — screen lock prevents unauthorised access
[NIST SP 800-171]  3.1.10 (Use session lock after period of inactivity)$p$, $p$Medium$p$, $p$Clean-desk policy document; physical security audit records confirming compliance; screen lock policy configuration (auto-lock after ≤5 minutes of inactivity)$p$, $p$Implement and communicate a clean-desk and clear-screen policy. Configure workstations to auto-lock after a maximum of 5 minutes of inactivity. Conduct unannounced physical security walkthrough audits at least quarterly.$p$, $p$all$p$, $p$popia.s4.q04$p$),
  (4, $p$Security of Personal Information$p$, $p$NETWORK & SYSTEM SECURITY$p$, 5, $p$Is personal information encrypted at rest (AES-256 or equivalent) and in transit (TLS 1.2 minimum, TLS 1.3 preferred) across all systems and communication channels?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.8.24 (Use of cryptography)
[ISO 27002]  cl.8.24 (Use of cryptography)
[ISO 27701]  cl.6.10 (Cryptographic controls for PII)
[CIS Controls v8 IG1]  CIS 3.11 — Encrypt Sensitive Data at Rest; CIS 3.10 — Encrypt Sensitive Data in Transit
[NIST CSF 2.0]  PR.DS-01 (Data-at-rest protected); PR.DS-02 (Data-in-transit protected)
[Cyber Essentials]  CE — 'Secure Configuration': disable insecure protocols (SSL, TLS 1.0/1.1); CE+ — encryption verified during assessment
[NIST SP 800-171]  3.13.8 (Implement cryptographic mechanisms for transmission); 3.13.16 (Protect CUI at rest)$p$, $p$Critical$p$, $p$Encryption policy; database encryption configuration (TDE or equivalent); TLS certificate inspection reports; email encryption configuration; penetration test results confirming encryption standards$p$, $p$Implement AES-256 encryption for all personal information at rest in databases, file stores, and backup media. Enforce TLS 1.2 minimum (TLS 1.3 preferred) for all data in transit. Disable deprecated protocols (SSL, TLS 1.0, TLS 1.1). Document the encryption standard in the Information Security Policy.$p$, $p$all$p$, $p$popia.s4.q05$p$),
  (4, $p$Security of Personal Information$p$, $p$NETWORK & SYSTEM SECURITY$p$, 6, $p$Are firewalls, network segmentation, intrusion detection/prevention systems (IDS/IPS), and endpoint protection deployed and actively monitored?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.8.20 (Networks security); A.8.21 (Security of network services); A.8.7 (Protection against malware)
[ISO 27002]  cl.8.20; cl.8.21; cl.8.7
[CIS Controls v8 IG1]  CIS 4.4 — Use Unique Passwords (network devices); CIS 9.2 — Use DNS Filtering Services; CIS 10.1 — Deploy and Maintain Anti-Malware Software; CIS 12.1 — Ensure Network Infrastructure Up-to-Date
[NIST CSF 2.0]  PR.PS-05 (Software lifecycle managed); DE.CM-01 (Networks monitored); PR.AA-05 (Physical/logical access managed)
[Cyber Essentials]  CE Control 1 — Boundary Firewalls & Internet Gateways (required); CE Control 5 — Malware Protection (required)
[NIST SP 800-171]  3.13.1 (Monitor, control, protect communications at boundaries); 3.14.2 (Provide protection from malware)$p$, $p$Critical$p$, $p$Network architecture diagram; firewall rule review records; IDS/IPS alert and response logs; EDR/antivirus management console reports; quarterly security operations review$p$, $p$Implement network segmentation to isolate systems processing personal information. Deploy an EDR solution on all endpoints. Conduct quarterly firewall rule reviews. Review IDS/IPS alerts daily and respond within defined SLAs.$p$, $p$all$p$, $p$popia.s4.q06$p$),
  (4, $p$Security of Personal Information$p$, $p$NETWORK & SYSTEM SECURITY$p$, 7, $p$Is vulnerability management (scanning, patching, and penetration testing) conducted on a regular basis for all systems processing personal information?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.8.8 (Management of technical vulnerabilities)
[ISO 27002]  cl.8.8 (Management of technical vulnerabilities)
[CIS Controls v8 IG1]  CIS 7.1 — Establish and Maintain a Vulnerability Management Process; CIS 7.2 — Establish and Maintain a Remediation Process; CIS 7.3 — Perform Automated Operating System Patch Management; CIS 7.4 — Perform Automated Application Patch Management
[NIST CSF 2.0]  ID.RA-01 (Vulnerabilities identified); ID.RA-04 (Potential impacts identified); PR.PS-02 (Software maintained)
[Cyber Essentials]  CE Control 4 — Patch Management (required): critical patches within 14 days, unsupported software removed
[NIST SP 800-171]  3.11.2 (Scan for vulnerabilities); 3.11.3 (Remediate vulnerabilities)$p$, $p$Critical$p$, $p$Monthly vulnerability scan reports; patch management records (critical patches within 14 days, high within 30 days); annual penetration test reports; remediation tracking log$p$, $p$Implement monthly vulnerability scanning for all in-scope systems. Define patch SLAs: critical within 14 days, high within 30 days, medium within 90 days. Conduct an annual penetration test by a qualified independent party. Track and report on remediation progress.$p$, $p$all$p$, $p$popia.s4.q07$p$),
  (4, $p$Security of Personal Information$p$, $p$ACCESS CONTROL & IDENTITY MANAGEMENT$p$, 8, $p$Is a formal joiners-movers-leavers (JML) process in place, ensuring that user access is provisioned, modified, and revoked promptly and that timely revocation is confirmed for all systems?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.5.18 (Access rights); A.6.1 (Screening)
[ISO 27002]  cl.5.18 (Access rights); cl.6.1 (Screening — background checks)
[ISO 27701]  cl.6.4 (Roles and responsibilities); cl.7.2.2 (Authorised users)
[CIS Controls v8 IG1]  CIS 5.1 — Establish and Maintain an Inventory of Accounts; CIS 5.3 — Disable Dormant Accounts; CIS 6.2 — Establish an Access Revoking Process
[NIST CSF 2.0]  PR.AA-01 (Identities managed); PR.AA-06 (Identity assertions proofed and bound); GV.OC-03 (Legal requirements understood)
[Cyber Essentials]  CE Control 3 — Access Control: accounts limited, leavers removed promptly
[NIST SP 800-171]  3.1.1 (Limit system access to authorised users); 3.1.2 (Limit access to authorised transaction types)$p$, $p$Critical$p$, $p$JML procedure; onboarding/offboarding checklists integrated with HR; access provisioning and de-provisioning logs; evidence of access removed within 24 hours for leavers; quarterly recertification reports$p$, $p$Integrate the JML process with HR systems to trigger automated notifications to IT within one business day of any joiner, mover, or leaver event. Verify access removal within 24 hours for leavers. Conduct quarterly access recertification reviews.$p$, $p$all$p$, $p$popia.s4.q08$p$),
  (4, $p$Security of Personal Information$p$, $p$ACCESS CONTROL & IDENTITY MANAGEMENT$p$, 9, $p$Is Role-Based Access Control (RBAC) implemented with least-privilege principles, and are access rights formally requested, approved, and documented?$p$, $p$$p$, $p$POPIA s.19 | ISO 27002 cl.8.2 (Privileged access rights), cl.5.18$p$, $p$Critical$p$, $p$RBAC matrix; access request and approval forms; system access reports showing alignment to RBAC; privileged access management (PAM) solution evidence$p$, $p$Develop and maintain an RBAC matrix aligned to job roles. Require formal access requests with manager and system owner approval. Implement a Privileged Access Management (PAM) solution for all administrative accounts. Conduct quarterly access rights reviews.$p$, $p$large$p$, $p$popia.s4.q09$p$),
  (4, $p$Security of Personal Information$p$, $p$ACCESS CONTROL & IDENTITY MANAGEMENT$p$, 10, $p$Is Multi-Factor Authentication (MFA) enforced for all remote access, privileged accounts, cloud platforms, and systems processing special/sensitive personal information?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.8.5 (Secure authentication)
[ISO 27002]  cl.8.5 (Secure authentication)
[CIS Controls v8 IG1]  CIS 6.3 — Require MFA for Externally-Exposed Applications; CIS 6.4 — Require MFA for Remote Network Access; CIS 6.5 — Require MFA for Administrative Access
[NIST CSF 2.0]  PR.AA-03 (Users, services, hardware authenticated); PR.AA-05 (Access permissions minimised)
[Cyber Essentials]  CE Control 3 — Access Control: multi-factor authentication for cloud/remote access (CE+ requirement); CE 2022 update requires MFA for remote access and cloud services
[NIST SP 800-171]  3.5.3 (Use multifactor authentication for local/network/remote access)$p$, $p$Critical$p$, $p$MFA policy; MFA configuration evidence (Azure AD Conditional Access, Okta, Duo, etc.); list of systems with MFA enforced; exceptions register with compensating controls$p$, $p$Enable and enforce MFA on all remote access (VPN, RDP), cloud platforms (Microsoft 365, AWS, GCP, Azure), and any system processing sensitive personal information. Maintain an exceptions register for any systems where MFA cannot be implemented, with compensating controls documented.$p$, $p$all$p$, $p$popia.s4.q10$p$),
  (4, $p$Security of Personal Information$p$, $p$ACCESS CONTROL & IDENTITY MANAGEMENT$p$, 11, $p$Is there a documented password / credential policy enforcing minimum complexity, length (minimum 12 characters), expiry, prohibition on reuse, and account lockout after failed attempts?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.5.17 (Authentication information)
[ISO 27002]  cl.5.17 (Authentication information)
[CIS Controls v8 IG1]  CIS 5.2 — Use Unique Passwords; CIS 6.1 — Establish an Access Granting Process (password standards)
[NIST CSF 2.0]  PR.AA-01 (Identities managed); PR.AA-03 (Users authenticated)
[Cyber Essentials]  CE Control 3 — Access Control: password policy required; accounts locked after failed attempts; default passwords changed
[NIST SP 800-171]  3.5.7 (Enforce minimum password complexity); 3.5.8 (Prohibit password reuse); 3.5.10 (Store passwords cryptographically protected)$p$, $p$High$p$, $p$Password policy document; Active Directory / IdP configuration confirming policy enforcement; account lockout configuration (max 5 attempts); prohibition on last 12 passwords reuse$p$, $p$Implement a password policy meeting NIST SP 800-63B recommendations: minimum 12 characters, complexity, 90-day expiry (or consider length-based expiry per NIST), lockout after 5 failed attempts, prohibition on reuse of last 12 passwords. Enforce via Active Directory Group Policy or IdP.$p$, $p$all$p$, $p$popia.s4.q11$p$),
  (4, $p$Security of Personal Information$p$, $p$DATA LOSS PREVENTION & REMOVABLE MEDIA$p$, 12, $p$Is a Data Loss Prevention (DLP) solution deployed to detect and prevent unauthorised transfer or exfiltration of personal information via email, web uploads, cloud sync, or removable media?$p$, $p$$p$, $p$POPIA s.19 | ISO 27002 cl.8.12 (Data leakage prevention)$p$, $p$High$p$, $p$DLP solution configuration and policy rules; DLP alert and incident logs; monthly DLP incident report; evidence of policy refinement based on false positives/negatives$p$, $p$Deploy an enterprise DLP solution covering endpoint, email, and network channels. Define DLP policies for personal information categories (PII, special PI, payment card data). Review DLP alerts weekly. Report on DLP incidents monthly to the IO.$p$, $p$large$p$, $p$popia.s4.q12$p$),
  (4, $p$Security of Personal Information$p$, $p$DATA LOSS PREVENTION & REMOVABLE MEDIA$p$, 13, $p$Are removable media ports (USB, SD, CD/DVD) disabled or strictly controlled on endpoints processing personal information, with exceptions subject to formal approval?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
[ISO 27001]  A.7.10 (Storage media)
[ISO 27002]  cl.7.10 (Storage media)
[CIS Controls v8 IG1]  CIS 10.3 — Disable Autorun and Autoplay for Removable Media; CIS 10.4 — Configure Automatic Anti-Malware Scanning of Removable Media
[NIST CSF 2.0]  PR.DS-01 (Data-at-rest protected); PR.AA-05 (Access permissions minimised)
[Cyber Essentials]  CE Control 2 — Secure Configuration: disable unnecessary ports and services including USB autorun
[NIST SP 800-171]  3.8.7 (Control use of removable media on system components); 3.8.8 (Prohibit use of portable storage devices)$p$, $p$High$p$, $p$Endpoint management (SCCM, Intune, Jamf) configuration showing USB restriction; exceptions register; approved device whitelist; DLP policy covering removable media$p$, $p$Configure endpoint management to block all removable media by default. Establish a formal exception process requiring management and IO approval. Whitelist approved, encrypted USB devices only. Log all approved removable media usage.$p$, $p$all$p$, $p$popia.s4.q13$p$),
  (4, $p$Security of Personal Information$p$, $p$DATA LOSS PREVENTION & REMOVABLE MEDIA$p$, 14, $p$Are all laptops and mobile devices used to access personal information subject to full-disk encryption, MDM enrolment, and remote wipe capability?$p$, $p$$p$, $p$[POPIA]  s.19 (Security safeguards)
